const DEFAULT_PRECISION: i32 = 6;

/// Formats an `f32` like C++ iostreams with `std::defaultfloat` and
/// the default precision of six significant digits.
pub fn format_f32(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            "-nan".to_owned()
        } else {
            "nan".to_owned()
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            "-inf".to_owned()
        } else {
            "inf".to_owned()
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            "-0".to_owned()
        } else {
            "0".to_owned()
        };
    }

    let scientific = format!("{:.*e}", (DEFAULT_PRECISION - 1) as usize, value);
    let exponent = scientific
        .rsplit_once('e')
        .and_then(|(_, exponent)| exponent.parse::<i32>().ok())
        .expect("Rust scientific notation always contains an exponent");

    if (-4..DEFAULT_PRECISION).contains(&exponent) {
        let decimal_places = (DEFAULT_PRECISION - 1 - exponent) as usize;
        trim_fraction_zeros(format!("{:.*}", decimal_places, value))
    } else {
        format_scientific(&scientific)
    }
}

fn trim_fraction_zeros(mut text: String) -> String {
    if text.contains('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
    }
    text
}

fn format_scientific(scientific: &str) -> String {
    let (mantissa, exponent) = scientific
        .split_once('e')
        .expect("Rust scientific notation always contains an exponent");
    let mantissa = trim_fraction_zeros(mantissa.to_owned());
    let exponent = exponent
        .parse::<i32>()
        .expect("Rust scientific notation always contains a numeric exponent");
    let sign = if exponent < 0 { '-' } else { '+' };
    format!("{}e{}{:02}", mantissa, sign, exponent.abs())
}

