/// Parses the leading floating-point token accepted by `std::stof` for
/// ordinary decimal, infinity, and NaN inputs.
pub fn parse_stof(input: &str) -> f32 {
    let text = input.trim_start_matches([' ', '\t', '\n', '\r', '\x0b', '\x0c']);
    let end = floating_token_end(text);

    if end == 0 {
        panic!("stof: no conversion could be performed");
    }

    text[..end]
        .parse::<f32>()
        .unwrap_or_else(|_| panic!("stof: argument out of range"))
}

fn floating_token_end(text: &str) -> usize {
    let lower = text.to_ascii_lowercase();
    for word in ["infinity", "inf", "nan"] {
        if lower.starts_with(word) {
            return word.len();
        }
        if lower.starts_with(&format!("+{word}")) || lower.starts_with(&format!("-{word}")) {
            return word.len() + 1;
        }
    }

    let bytes = text.as_bytes();
    let mut index = 0;

    if matches!(bytes.get(index), Some(b'+' | b'-')) {
        index += 1;
    }

    let digits_before_point = consume_digits(bytes, &mut index);

    let mut digits_after_point = 0;
    if bytes.get(index) == Some(&b'.') {
        index += 1;
        digits_after_point = consume_digits(bytes, &mut index);
    }

    if digits_before_point + digits_after_point == 0 {
        return 0;
    }

    let mantissa_end = index;
    if matches!(bytes.get(index), Some(b'e' | b'E')) {
        index += 1;
        if matches!(bytes.get(index), Some(b'+' | b'-')) {
            index += 1;
        }
        if consume_digits(bytes, &mut index) == 0 {
            return mantissa_end;
        }
    }

    index
}

fn consume_digits(bytes: &[u8], index: &mut usize) -> usize {
    let start = *index;
    while bytes.get(*index).is_some_and(u8::is_ascii_digit) {
        *index += 1;
    }
    *index - start
}

